/*
 * mtp-example — a starter µTest++ test for this board.
 * GENERATED by micro-os-scaffold (--micro-test-plus).
 *
 * There is no list of suites here. Each suite registers itself, in its own
 * source file, with a static object:
 *
 *   mt::static_suite suite_basics{ "02 - Basics", mtp_board::runner (),
 *                                  [] (mt::suite& ts) { ... } };
 *
 * Adding a file that defines one is enough: the runner discovers it through
 * the C++ static constructors and runs it, sorted by name (hence the
 * "00 -", "01 -" prefixes). The suites of this starter test are:
 *
 *   00 - Cores     the other cores joined (boards with SMP boot helpers)
 *   01 - Runtime   what every µTest++ board must provide: the boot code ran
 *                  the static constructors, malloc works, the heap and sbrk
 *                  agree with the linker script's heap
 *   02 - Basics    a few checks to copy from
 *
 * The command line reaches os_main () through semihosting (OpenOCD
 * "arm semihosting_cmdline ...", QEMU "-semihosting-config ...,arg=...").
 * mtp_board::run () parses it, so the CTest runner can ask for the complete
 * TAP report in a file with --output-file <path>.
 */
#include <mtp_board.hpp>

int
os_main (int argc, char* argv[])
{
  mtp_board::start ("mtp-example");
#if defined(MTP_HAS_SMP_BOOT) && MTP_HAS_SMP_BOOT
  mtp_board::release_cores ();
#endif
  return mtp_board::run (argc, argv);
}

#include <mtp_startup.hpp>
